 1→import {
 2→  ChangeDetectionStrategy,
 3→  Component,
 4→  computed,
 5→  input,
 6→  model,
 7→} from "@angular/core";
 8→import { DrawerPanelComponent } from "@aspect/ui";
 9→import type { AuditEntry } from "../core/audit-api.service";
10→
11→@Component({
12→  selector: "tfc-logs-drawer",
13→  changeDetection: ChangeDetectionStrategy.OnPush,
14→  imports: [DrawerPanelComponent],
15→  template: `
16→    <ui-drawer-panel side="right" [open]="open()" (closed)="open.set(false)">
17→      <h2 drawerTitle>Logs</h2>
18→      <div class="logs-list">
19→        @for (entry of sortedLogs(); track entry.id) {
20→          <div class="log-entry" data-testid="log-entry" [attr.data-type]="entry.entry_type">
21→            <span class="log-time">{{ formatPT(entry.play_time_ms) }}</span>
22→            <span class="log-action">{{ entry.action }}</span>
23→            @if (entry.target_id) {
24→              <span class="log-target">{{ entry.target_id }}</span>
25→            }
26→            @if (decisionSummary(entry); as summary) {
27→              <span class="log-detail">{{ summary }}</span>
28→            }
29→          </div>
30→        } @empty {
31→          <p class="logs-empty">No events yet.</p>
32→        }
33→      </div>
34→    </ui-drawer-panel>
35→  `,
36→})
37→export class LogsDrawerComponent {
38→  readonly open = model(false);
39→  readonly logs = input<AuditEntry[]>([]);
40→
41→  protected sortedLogs = computed(() =>
42→    [...this.logs()].sort((a, b) => a.play_time_ms - b.play_time_ms),
43→  );
44→
45→  protected formatPT(ms: number): string {
46→    const s = Math.floor(ms / 1000);
47→    const m = Math.floor(s / 60);
48→    return `${m}:${String(s % 60).padStart(2, "0")}`;
49→  }
50→
51→  protected decisionSummary(entry: AuditEntry): string | null {
52→    if (entry.entry_type !== "decision_closed" || !entry.details) return null;
53→    const ids = entry.details["selected_option_ids"] as string[] | undefined;
54→    if (!ids?.length) return null;
55→    return ids.join(", ");
56→  }
57→}
