 1→import { ComponentFixture, TestBed } from "@angular/core/testing";
 2→import { Component, signal } from "@angular/core";
 3→import { LogsDrawerComponent } from "./logs-drawer.component";
 4→import type { AuditEntry } from "../core/audit-api.service";
 5→
 6→@Component({
 7→  selector: "test-host",
 8→  imports: [LogsDrawerComponent],
 9→  template: `<tfc-logs-drawer [(open)]="open" [logs]="logs()" />`,
10→})
11→class TestHost {
12→  open = signal(true);
13→  logs = signal<AuditEntry[]>([]);
14→}
15→
16→function makeEntry(overrides: Partial<AuditEntry> = {}): AuditEntry {
17→  return {
18→    id: 1,
19→    exercise_id: 1,
20→    entry_type: "phase_change",
21→    action: "started",
22→    actor_id: null,
23→    actor_name: null,
24→    target_type: null,
25→    target_id: null,
26→    play_time_ms: 0,
27→    real_time_ms: 0,
28→    details: null,
29→    created_at: "2026-01-01T00:00:00Z",
30→    ...overrides,
31→  };
32→}
33→
34→describe("LogsDrawerComponent", () => {
35→  let fixture: ComponentFixture<TestHost>;
36→  let host: TestHost;
37→
38→  beforeEach(async () => {
39→    await TestBed.configureTestingModule({
40→      imports: [TestHost],
41→    }).compileComponents();
42→    fixture = TestBed.createComponent(TestHost);
43→    host = fixture.componentInstance;
44→    fixture.detectChanges();
45→  });
46→
47→  it("should render log entries", () => {
48→    host.logs.set([
49→      makeEntry({ id: 1, entry_type: "phase_change", action: "started", play_time_ms: 0 }),
50→      makeEntry({ id: 2, entry_type: "event_change", action: "triggered", play_time_ms: 5000, target_id: "evt-1" }),
51→    ]);
52→    fixture.detectChanges();
53→    const entries = fixture.nativeElement.querySelectorAll('[data-testid="log-entry"]');
54→    expect(entries.length).toBe(2);
55→  });
56→
57→  it("should show drawer title as Logs", () => {
58→    fixture.detectChanges();
59→    expect(fixture.nativeElement.textContent).toContain("Logs");
60→  });
61→
62→  it("should show empty message when no logs", () => {
63→    fixture.detectChanges();
64→    expect(fixture.nativeElement.textContent).toContain("No events yet.");
65→  });
66→
67→  it("should sort entries by play_time_ms", () => {
68→    host.logs.set([
69→      makeEntry({ id: 2, action: "second", play_time_ms: 5000 }),
70→      makeEntry({ id: 1, action: "first", play_time_ms: 1000 }),
71→    ]);
72→    fixture.detectChanges();
73→    const entries = fixture.nativeElement.querySelectorAll('[data-testid="log-entry"]');
74→    expect(entries[0].textContent).toContain("first");
75→    expect(entries[1].textContent).toContain("second");
76→  });
77→
78→  it("should format play time as m:ss", () => {
79→    host.logs.set([
80→      makeEntry({ id: 1, play_time_ms: 65000 }),
81→    ]);
82→    fixture.detectChanges();
83→    expect(fixture.nativeElement.textContent).toContain("1:05");
84→  });
85→});
