 38→@Component({
 39→  selector: "tfc-player-view",
 40→  changeDetection: ChangeDetectionStrategy.OnPush,
 41→  providers: [ExerciseStore, TickService],
 42→  imports: [
 43→    ClockDisplayComponent,
 44→    PhaseBadgeComponent,
 45→    AmbientBackgroundComponent,
 46→    BriefingOverlayComponent,
 47→    LogsDrawerComponent,
 48→    StressBarComponent,
 49→    ButtonDirective,
 50→    RoleCardComponent,
 51→    SystemStatusBoardComponent,
 52→  ],
 53→  templateUrl: "./player-view.html",
 54→})
 55→export class PlayerView implements OnInit, OnDestroy {
 56→  protected readonly store = inject(ExerciseStore);
 57→  protected readonly domain = inject(DomainService);
 58→  private readonly api = inject(EngineApiService);
 59→  private readonly decisionApi = inject(DecisionApiService);
 60→  private readonly auditApi = inject(AuditApiService);
 61→  protected readonly logsOpen = signal(false);
 62→  protected readonly auditLog = signal<AuditEntry[]>([]);
 63→  private readonly ws = inject(ExerciseWsService);
 64→  private readonly router = inject(Router);
 65→  private readonly route = inject(ActivatedRoute);
 66→  protected readonly roleLabel = signal("Advisor");
 67→  protected readonly beginningExercise = signal(false);
 68→  private readonly exerciseId = signal(1);
 69→  private readonly participantId = signal("");
 70→  private readonly tick = inject(TickService);
 71→  private snapshotLoaded = false;
 72→  private sub: Subscription | null = null;
 73→  private connSub: Subscription | null = null;
 74→
 75→  protected readonly activeDecisions = computed(() => {
 76→    const role = this.store.playerRole();
 77→    return this.store.openDecisions().filter((d) => {
 78→      if (!d.target_roles || d.target_roles.length === 0) return true;
 79→      if (role === "all_roles" || role === "all_advisors" || role === "solo_player") return true;
 80→      return d.target_roles.includes(role);
 81→    });
 82→  });
 83→
 84→  protected readonly isMultiRole = computed(() => {
 85→    const role = this.store.playerRole();
 86→    return role === "all_advisors" || role === "solo_player" || role === "all_roles";
 87→  });
 88→
 89→  protected readonly submittedRoles = signal<Set<string>>(new Set());
 90→
 91→  protected readonly currentTurnEvent = computed(() => {
 92→    const decisions = this.activeDecisions();
 93→    if (decisions.length === 0) return null;
 94→    const decision = decisions[0];
 95→    if (!decision.event_id) return null;
 96→    return this.store.events().find((e) => e.id === decision.event_id) ?? null;
 97→  });
 98→
 99→  protected readonly roleCards = computed(() => {
100→    const allRoles = this.store.context()?.roles ?? [];
101→    const event = this.currentTurnEvent();
102→    const decision = this.activeDecisions()[0] ?? null;
103→    const role = this.store.playerRole();
104→    const multiRole = this.isMultiRole();
105→    const showDecisionMaker =
106→      role === "all_roles" || role === "solo_player" || this.store.isPracticeMode();
107→    // Single-role players see only their own role card
108→    const roles = multiRole ? allRoles : allRoles.filter((r) => r.id === role);
109→    return buildRoleCards(roles, event, decision, this.submittedRoles(), showDecisionMaker);
110→  });
111→
112→  private _lastDecisionId: string | null = null;
113→  private readonly resetSubmittedRolesEffect = effect(() => {
114→    const id = this.activeDecisions()[0]?.id ?? null;
115→    // Only reset when the decision ID actually changes (not on every WS push)
116→    if (id && id !== this._lastDecisionId) {
117→      this._lastDecisionId = id;
118→      this.submittedRoles.set(new Set());
119→    }
120→  });
121→
122→  // Turn advancement is backend-driven: closing a decision triggers the
123→  // next event in sequence automatically via engine.force_trigger_next_decision.
124→
125→  ngOnInit(): void {
126→    const params = this.route.snapshot.queryParams;
127→    const id = Number(params["exerciseId"] ?? 1);
128→    const pId = String(params["participantId"] ?? "");
129→    const role = String(params["role"] ?? "player");
130→    const gameMode = String(params["gameMode"] ?? "");
131→    this.exerciseId.set(id);
132→    this.participantId.set(pId);
133→    this.store.setParticipantId(pId);
134→    this.store.setPlayerRole(role);
135→    if (gameMode) {
136→      this.store.setGameMode(gameMode);
137→    }
138→    const practiceMode = params["practiceMode"] === "true";
139→    this.store.setPracticeMode(practiceMode);
140→    this.ws.connect(id, "player", pId || undefined);
141→    this.sub = this.ws.messages$.subscribe((msg) =>
142→      handlePlayerWsMessage(msg, this.store, () => this.onExerciseStopped()),
143→    );
144→    this.loadSnapshot(id);
145→    this.decisionApi.getContext(id).subscribe({
146→      next: (ctx) =>
147→        resolvePlayerRole(ctx, role, gameMode, this.store, this.roleLabel),
148→      error: () => {},
149→    });
150→    this.decisionApi.getEngineDecisions(id).subscribe({
151→      next: (decisions) => this.store.applyDecisions(decisions),
152→      error: () => {},
153→    });
154→    this.connSub = this.ws.connected$.subscribe((connected) => {
155→      if (connected && this.snapshotLoaded) this.loadSnapshot(id);
156→    });
157→    this.tick.start(this.store);
158→  }
159→
160→  private loadSnapshot(exerciseId: number): void {
161→    this.api.snapshot(exerciseId).subscribe({
162→      next: (snap) => {
163→        this.snapshotLoaded = true;
164→        this.store.applySnapshot(snap);
165→      },
166→      error: () => this.store.setError("Failed to load snapshot"),
167→    });
168→    this.auditApi.getLog(exerciseId).subscribe({
169→      next: (log) => this.auditLog.set(log),
170→      error: (e) => console.warn("Failed to fetch audit log", e),
171→    });
172→  }
173→
174→  protected onBeginExercise(): void {
175→    this.beginningExercise.set(true);
176→    this.api.begin(this.exerciseId()).subscribe({
177→      next: (change) => {
178→        this.store.applyPhaseChange(change.phase);
179→        this.store.applyTimeUpdate(change.time);
180→        this.beginningExercise.set(false);
181→      },
182→      error: () => {
183→        this.store.setError("Failed to begin exercise");
184→        this.beginningExercise.set(false);
185→      },
186→    });
187→  }
188→
189→  protected onStop(): void {
190→    this.api.stop(this.exerciseId()).subscribe({
191→      next: () => this.onExerciseStopped(),
192→    });
193→  }
194→
195→  private onExerciseStopped(): void {
196→    this.ws.disconnect();
197→    this.router.navigate(["/"]);
198→  }
199→
200→  ngOnDestroy(): void {
201→    this.tick.stop();
202→    this.ws.disconnect();
203→    this.sub?.unsubscribe();
204→    this.connSub?.unsubscribe();
205→  }
206→  protected onRoleCardSubmitted(submission: RoleCardSubmission): void {
207→    const decision = this.activeDecisions()[0];
208→    if (!decision) return;
209→    const role = this.store.context()?.roles?.find(
210→      (r) => r.id === submission.roleId,
211→    );
212→    if (role?.player_type === "decision_maker") {
213→      submitDecision(
214→        this.decisionApi,
215→        this.store,
216→        this.exerciseId(),
217→        decision,
218→        submission,
219→      );
220→    } else {
221→      submitRoleRecommendation(
222→        this.decisionApi,
223→        this.exerciseId(),
224→        decision,
225→        this.participantId(),
226→        { roleId: submission.roleId, selectedOptions: submission.selectedOptions, freeText: submission.freeText },
227→      );
228→    }
229→    const updated = new Set(this.submittedRoles());
230→    updated.add(submission.roleId);
231→    this.submittedRoles.set(updated);
232→  }
233→}
