227→export class GameMasterView implements OnInit, OnDestroy {
228→  protected readonly store = inject(ExerciseStore);
229→  protected readonly domain = inject(DomainService);
230→  private readonly api = inject(EngineApiService);
231→  private readonly exerciseApi = inject(ExerciseApiService);
232→  private readonly decisionApi = inject(DecisionApiService);
233→  private readonly ws = inject(ExerciseWsService);
234→  private readonly router = inject(Router);
235→  private readonly route = inject(ActivatedRoute);
236→  private readonly auditApi = inject(AuditApiService);
237→  protected readonly selectedDecision = signal<DecisionDetail | null>(null);
238→  protected readonly exerciseId = signal<number | null>(null);
239→  protected readonly logsOpen = signal(false);
240→  protected readonly auditLog = signal<AuditEntry[]>([]);
241→  private sub: Subscription | null = null;
242→  private connSub: Subscription | null = null;
243→  private readonly tick = inject(TickService);
244→
245→  ngOnInit(): void {
246→    const params = this.route.snapshot.queryParams;
247→    const eId = Number(params["exerciseId"] ?? 0);
248→    if (eId) {
249→      this.exerciseId.set(eId);
250→      this.connectExercise(eId);
251→    }
252→  }
253→
254→  protected onExerciseSelected(exercise: ExerciseResponse): void {
255→    if (exercise.domain_id != null) {
256→      const domainMap: Record<number, string> = {
257→        1: "cybersecurity",
258→        2: "healthcare",
259→        3: "military",
260→      };
261→      this.domain.setDomain(domainMap[exercise.domain_id] ?? "default");
262→    }
263→    this.exerciseId.set(exercise.id);
264→    this.connectExercise(exercise.id);
265→  }
266→
267→  protected onScenarioSelected({
268→    scenario,
269→    gameMode,
270→  }: ScenarioSelection): void {
271→    if (scenario.domain_id != null) {
272→      const domainMap: Record<number, string> = {
273→        1: "cybersecurity",
274→        2: "healthcare",
275→        3: "military",
276→      };
277→      this.domain.setDomain(domainMap[scenario.domain_id] ?? "default");
278→    }
279→    this.exerciseApi
280→      .create({
281→        title: scenario.title,
282→        scenario_id: scenario.id,
283→        time_factor: scenario.content?.default_time_factor ?? 1.0,
284→        game_mode: gameMode,
285→      })
286→      .subscribe({
287→        next: (ex) => {
288→          this.router.navigate(["/waiting-room"], {
289→            queryParams: { exerciseId: ex.id },
290→          });
291→        },
292→        error: () => this.store.setError("Failed to create exercise"),
293→      });
294→  }
295→
296→  private connectExercise(id: number): void {
297→    this.ws.connect(id, "gm");
298→    this.sub = this.ws.messages$.subscribe((msg) =>
299→      handleGmWsMessage(msg, this.store, () => this.onExerciseStopped()),
300→    );
301→    this.loadSnapshot(id);
302→    this.decisionApi
303→      .getContext(id)
304→      .subscribe({ next: (ctx) => this.store.setContext(ctx) });
305→    this.connSub = this.ws.connected$.subscribe((c) => {
306→      if (c) this.loadSnapshot(id);
307→    });
308→    this.tick.start(this.store);
309→  }
310→
311→  ngOnDestroy(): void {
312→    this.tick.stop();
313→    this.ws.disconnect();
314→    this.sub?.unsubscribe();
315→    this.connSub?.unsubscribe();
316→  }
317→
318→  private loadSnapshot(id: number): void {
319→    this.api.snapshot(id).subscribe({
320→      next: (snap) => this.store.applySnapshot(snap),
321→      error: () => this.store.setError("Failed to load snapshot"),
322→    });
323→    this.auditApi.getLog(id).subscribe({
324→      next: (log) => this.auditLog.set(log),
325→      error: (e) => console.warn("Failed to fetch audit log", e),
326→    });
327→  }
328→
329→  protected viewDecision(id: string): void {
330→    this.decisionApi.getDecisionDetail(Number(id)).subscribe({
331→      next: (detail) => this.selectedDecision.set(detail),
332→    });
333→  }
334→
335→  protected closeDecision(id: string): void {
336→    this.decisionApi.closeEngineDecision(this.exerciseId()!, id).subscribe({
337→      next: () => this.store.closeDecision(id),
338→    });
339→  }
340→
341→  protected onStart(): void {
342→    startExercise(this.api, this.store, this.exerciseId()!);
343→  }
344→  protected onPause(): void {
345→    pauseExercise(this.api, this.store, this.exerciseId()!);
346→  }
347→  protected onReset(): void {
348→    resetExercise(this.api, this.store, this.exerciseId()!);
349→  }
350→  protected onComplete(): void {
351→    completeExercise(this.api, this.store, this.exerciseId()!);
352→  }
353→  protected onStop(): void {
354→    stopExercise(this.api, this.exerciseId()!, () => this.onExerciseStopped());
355→  }
356→  private onExerciseStopped(): void {
357→    this.ws.disconnect();
358→    this.router.navigate(["/"]);
359→  }
360→  protected onSpeedChange(e: Event): void {
361→    const target = e.target;
362→    if (!(target instanceof HTMLInputElement)) return;
363→    this.api
364→      .setSpeed(this.exerciseId()!, parseFloat(target.value))
365→      .subscribe();
366→  }
367→
368→  private eid(): number {
369→    return this.exerciseId()!;
370→  }
371→  protected triggerEvent(id: string): void {
372→    this.api.triggerEvent(this.eid(), id).subscribe();
373→  }
374→  protected cancelEvent(id: string): void {
375→    this.api.cancelEvent(this.eid(), id).subscribe();
376→  }
377→  protected completeEvent(id: string): void {
378→    this.api.completeEvent(this.eid(), id).subscribe();
379→  }
380→  protected activateIssue(id: string): void {
381→    this.api.activateIssue(this.eid(), id).subscribe();
382→  }
383→  protected mitigateIssue(id: string): void {
384→    this.api.mitigateIssue(this.eid(), id).subscribe();
385→  }
386→  protected resolveIssue(id: string): void {
387→    this.api.resolveIssue(this.eid(), id).subscribe();
388→  }
389→}
