 51→  id: number;
 52→  exercise_id: number;
 53→  issue_id: string;
 54→  title: string;
 55→  description: string;
 56→  question_type: string;
 57→  options: DecisionOption[] | null;
 58→  completion_mode: string;
 59→  status: string;
 60→  created_at: string;
 61→  closed_at: string | null;
 62→  responses: DecisionResponseItem[];
