 74→@Injectable({ providedIn: "root" })
 75→export class DecisionApiService {
 76→  private readonly http = inject(HttpClient);
 77→  private readonly base = environment.apiBaseUrl;
 78→
 79→  /** Get open decisions from the engine */
 80→  getEngineDecisions(exerciseId: number): Observable<ActiveDecision[]> {
 81→    return this.http.get<ActiveDecision[]>(
 82→      `${this.base}/api/exercises/${exerciseId}/engine/decisions`,
 83→    );
 84→  }
 85→
 86→  /** Submit a response to a DB-persisted decision */
 87→  submitResponse(
 88→    decisionId: number,
 89→    submission: DecisionSubmission,
 90→  ): Observable<DecisionResponseItem> {
 91→    return this.http.post<DecisionResponseItem>(
 92→      `${this.base}/api/decisions/${decisionId}/responses`,
 93→      submission,
 94→    );
 95→  }
 96→
 97→  /** Get decision details with all responses (for GM observation) */
 98→  getDecisionDetail(decisionId: number): Observable<DecisionDetail> {
 99→    return this.http.get<DecisionDetail>(
100→      `${this.base}/api/decisions/${decisionId}`,
101→    );
102→  }
103→
104→  /** List all decisions for an exercise */
105→  listDecisions(
106→    exerciseId: number,
107→    status?: string,
108→  ): Observable<DecisionDetail[]> {
109→    const params: Record<string, string | number> = { exercise_id: exerciseId };
110→    if (status) {
111→      params["status"] = status;
112→    }
113→    return this.http.get<DecisionDetail[]>(`${this.base}/api/decisions`, {
114→      params,
115→    });
116→  }
117→
118→  /** Submit an advisor recommendation on an open decision */
119→  submitRecommendation(
120→    exerciseId: number,
121→    decisionId: string,
122→    optionId: string,
123→    participantId: string,
124→    roleId?: string,
125→  ): Observable<unknown> {
126→    const body: Record<string, string> = {
127→      decision_id: decisionId,
128→      option_id: optionId,
