    SystemStatusBoardComponent,
    StressBarComponent,
  ],
  template: `
    @if (!exerciseId()) {
      <div class="flex flex-col gap-lg p-lg">
        <tfc-exercise-list
          (exerciseSelected)="onExerciseSelected($event)"
        />
        <tfc-scenario-picker (scenarioSelected)="onScenarioSelected($event)" />
      </div>
    } @else {
      <div class="exercise-layout">
        <header class="exercise-header">
          <span class="exercise-header__title">{{
            store.title() || domain.term("exercise") + " Control Panel"
          }}</span>
          <tfc-domain-selector />
