          <div class="exercise-header__clocks">
            <tfc-clock-display label="RT" [value]="store.rtClock()" />
            <tfc-speed-display [value]="store.speedFactor()" />
            <tfc-phase-badge [phase]="store.phase()" />
          </div>
        </header>

        <tfc-event-timeline
          [events]="store.events()"
          [issues]="store.issues()"
          [playTimeMs]="store.playTimeMs()"
        />

        <div class="exercise-overview">
          <tfc-gm-item-actions
            [events]="store.events()"
            [issues]="store.issues()"
            (triggerEvent)="triggerEvent($event)"
            (completeEvent)="completeEvent($event)"
            (cancelEvent)="cancelEvent($event)"
            (activateIssue)="activateIssue($event)"
            (mitigateIssue)="mitigateIssue($event)"
            (resolveIssue)="resolveIssue($event)"
          />

          <ui-collapsible-panel>
            <span panelTitle>{{ domain.term("decision") }}s</span>
            @for (decision of store.openDecisions(); track decision.id) {
              <div class="flex items-center justify-between p-sm border-b">
                <div>
                  <span class="text-sm font-medium">{{ decision.title }}</span>
                  <ui-badge variant="default">open</ui-badge>
                </div>
                <div class="flex gap-xs">
                  <button
                    uiButton
                    variant="outline"
                    size="sm"
                    (click)="viewDecision(decision.id)"
                  >
                    View
                  </button>
                  <button
                    uiButton
                    variant="destructive"
                    size="sm"
                    (click)="closeDecision(decision.id)"
                  >
                    Close
                  </button>
                </div>
              </div>
            } @empty {
              <p class="text-muted-foreground text-sm p-sm">
                No active decisions.
