  completeExercise,
  stopExercise,
} from "./gm-engine-actions";
import { EventTimelineComponent } from "./event-timeline.component";
import { ExerciseListComponent } from "./exercise-list.component";
import { GmItemActionsComponent } from "./gm-item-actions.component";
import { SystemStatusBoardComponent } from "../../shared/system-status-board.component";
import { StressBarComponent } from "../../shared/stress-bar.component";
import type { ExerciseResponse } from "../../core/exercise-api.service";
import { Subscription } from "rxjs";

@Component({
  selector: "tfc-game-master-view",
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [ExerciseStore, TickService],
  imports: [
    BadgeComponent,
    ButtonDirective,
    CollapsiblePanelComponent,
    ClockDisplayComponent,
    PhaseBadgeComponent,
    SpeedDisplayComponent,
    ContextPanelComponent,
    ScenarioPickerComponent,
    DomainSelectorComponent,
    PresenceIndicatorComponent,
    EventTimelineComponent,
    ExerciseListComponent,
    GmItemActionsComponent,
    LogsDrawerComponent,
    SystemStatusBoardComponent,
    StressBarComponent,
  ],
  template: `
    @if (!exerciseId()) {
      <div class="flex flex-col gap-lg p-lg">
        <tfc-exercise-list
          (exerciseSelected)="onExerciseSelected($event)"
        />
        <tfc-scenario-picker (scenarioSelected)="onScenarioSelected($event)" />
      </div>
    } @else {
      <div class="exercise-layout">
        <header class="exercise-header">
          <span class="exercise-header__title">{{
            store.title() || domain.term("exercise") + " Control Panel"
          }}</span>
          <tfc-domain-selector />
          <tfc-presence-indicator [participants]="store.participants()" />
          <div class="exercise-header__clocks">
            <tfc-clock-display label="RT" [value]="store.rtClock()" />
            <tfc-speed-display [value]="store.speedFactor()" />
            <tfc-phase-badge [phase]="store.phase()" />
          </div>
        </header>

        <tfc-event-timeline
          [events]="store.events()"
          [issues]="store.issues()"
          [playTimeMs]="store.playTimeMs()"
        />

        <div class="exercise-overview">
          <tfc-gm-item-actions
            [events]="store.events()"
            [issues]="store.issues()"
            (triggerEvent)="triggerEvent($event)"
            (completeEvent)="completeEvent($event)"
            (cancelEvent)="cancelEvent($event)"
            (activateIssue)="activateIssue($event)"
            (mitigateIssue)="mitigateIssue($event)"
            (resolveIssue)="resolveIssue($event)"
          />

          <ui-collapsible-panel>
            <span panelTitle>{{ domain.term("decision") }}s</span>
            @for (decision of store.openDecisions(); track decision.id) {
              <div class="flex items-center justify-between p-sm border-b">
                <div>
                  <span class="text-sm font-medium">{{ decision.title }}</span>
                  <ui-badge variant="default">open</ui-badge>
                </div>
                <div class="flex gap-xs">
                  <button
                    uiButton
                    variant="outline"
                    size="sm"
                    (click)="viewDecision(decision.id)"
                  >
                    View
                  </button>
                  <button
                    uiButton
                    variant="destructive"
                    size="sm"
                    (click)="closeDecision(decision.id)"
                  >
                    Close
                  </button>
                </div>
              </div>
            } @empty {
              <p class="text-muted-foreground text-sm p-sm">
                No active decisions.
              </p>
            }
          </ui-collapsible-panel>
        </div>

        <div class="exercise-details">
          <ui-collapsible-panel>
            <span panelTitle>Detail Panel</span>
            @if (selectedDecision(); as detail) {
              <p class="text-sm font-medium">{{ detail.title }}</p>
              <p class="text-sm text-muted-foreground">
                {{ detail.description }}
              </p>
              @for (resp of detail.responses; track resp.id) {
                <div class="flex items-center justify-between p-sm border-b">
                  <span class="text-sm">{{ resp.participant_name }}</span>
                  <span class="text-xs text-muted-foreground">{{
                    resp.submitted_at
                  }}</span>
                </div>
              } @empty {
                <p class="text-muted-foreground text-sm">No responses yet.</p>
              }
            } @else {
              <p class="text-muted-foreground text-sm">
                Select a decision to view context.
              </p>
            }
          </ui-collapsible-panel>
          @if (store.context(); as ctx) {
            <tfc-context-panel
              [title]="ctx.title"
              [briefing]="ctx.briefing"
              [objectives]="ctx.objectives"
              [rules]="ctx.rules"
            />
          }
          <tfc-system-status-board [systems]="store.systems()" />
          @if (store.score(); as score) {
            <tfc-stress-bar [stress]="score.stress" />
          }
        </div>

        <footer class="exercise-controls">
          <div class="exercise-controls__group">
            @if (store.phase() === "setup" || store.phase() === "paused") {
              <button uiButton variant="default" (click)="onStart()">
                {{ store.phase() === "setup" ? "Start" : "Resume" }}
              </button>
            }
            @if (store.phase() === "running") {
              <button uiButton variant="outline" (click)="onPause()">
                Pause
              </button>
            }
            @if (store.phase() !== "setup") {
              <button uiButton variant="outline" (click)="onComplete()">
                Complete
              </button>
              <button uiButton variant="destructive" (click)="onStop()">
                Stop
              </button>
            }
            <button uiButton variant="destructive" (click)="onReset()">
              Reset
            </button>
          </div>
          <button class="btn" data-variant="ghost" data-size="sm" (click)="logsOpen.set(true)">Logs</button>
