            <input
              type="range"
              min="0.5"
              max="10"
              step="0.5"
              [value]="store.speedFactor()"
              (input)="onSpeedChange($event)"
            />
          </tfc-speed-display>
        </footer>
      <tfc-logs-drawer [(open)]="logsOpen" [decisions]="store.decisions()" [roles]="store.context()?.roles ?? []" />
      </div>
    }
  `,
})
export class GameMasterView implements OnInit, OnDestroy {
  protected readonly store = inject(ExerciseStore);
  protected readonly domain = inject(DomainService);
  private readonly api = inject(EngineApiService);
  private readonly exerciseApi = inject(ExerciseApiService);
  private readonly decisionApi = inject(DecisionApiService);
  private readonly ws = inject(ExerciseWsService);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  protected readonly selectedDecision = signal<DecisionDetail | null>(null);
  protected readonly exerciseId = signal<number | null>(null);
  protected readonly logsOpen = signal(false);
  private sub: Subscription | null = null;
  private connSub: Subscription | null = null;
  private readonly tick = inject(TickService);

  ngOnInit(): void {
    const params = this.route.snapshot.queryParams;
    const eId = Number(params["exerciseId"] ?? 0);
    if (eId) {
      this.exerciseId.set(eId);
      this.connectExercise(eId);
    }
  }

  protected onExerciseSelected(exercise: ExerciseResponse): void {
    if (exercise.domain_id != null) {
      const domainMap: Record<number, string> = {
        1: "cybersecurity",
        2: "healthcare",
        3: "military",
      };
      this.domain.setDomain(domainMap[exercise.domain_id] ?? "default");
    }
    this.exerciseId.set(exercise.id);
    this.connectExercise(exercise.id);
  }

  protected onScenarioSelected({
    scenario,
    gameMode,
  }: ScenarioSelection): void {
    if (scenario.domain_id != null) {
      const domainMap: Record<number, string> = {
        1: "cybersecurity",
        2: "healthcare",
        3: "military",
      };
      this.domain.setDomain(domainMap[scenario.domain_id] ?? "default");
    }
    this.exerciseApi
      .create({
        title: scenario.title,
        scenario_id: scenario.id,
        time_factor: scenario.content?.default_time_factor ?? 1.0,
        game_mode: gameMode,
      })
      .subscribe({
        next: (ex) => {
          this.router.navigate(["/waiting-room"], {
            queryParams: { exerciseId: ex.id },
          });
        },
        error: () => this.store.setError("Failed to create exercise"),
      });
  }

  private connectExercise(id: number): void {
    this.ws.connect(id, "gm");
    this.sub = this.ws.messages$.subscribe((msg) =>
      handleGmWsMessage(msg, this.store, () => this.onExerciseStopped()),
    );
    this.loadSnapshot(id);
    this.decisionApi
      .getContext(id)
      .subscribe({ next: (ctx) => this.store.setContext(ctx) });
    this.connSub = this.ws.connected$.subscribe((c) => {
      if (c) this.loadSnapshot(id);
    });
    this.tick.start(this.store);
  }

  ngOnDestroy(): void {
    this.tick.stop();
    this.ws.disconnect();
    this.sub?.unsubscribe();
    this.connSub?.unsubscribe();
  }

  private loadSnapshot(id: number): void {
    this.api.snapshot(id).subscribe({
      next: (snap) => this.store.applySnapshot(snap),
      error: () => this.store.setError("Failed to load snapshot"),
    });
    this.auditApi.getLog(id).subscribe({
      next: (log) => this.auditLog.set(log),
      error: (e) => console.warn("Failed to fetch audit log", e),
    });
  }

  protected viewDecision(id: string): void {
    this.decisionApi.getDecisionDetail(Number(id)).subscribe({
      next: (detail) => this.selectedDecision.set(detail),
    });
  }

  protected closeDecision(id: string): void {
    this.decisionApi.closeEngineDecision(this.exerciseId()!, id).subscribe({
      next: () => this.store.closeDecision(id),
    });
  }

  protected onStart(): void {
    startExercise(this.api, this.store, this.exerciseId()!);
  }
  protected onPause(): void {
    pauseExercise(this.api, this.store, this.exerciseId()!);
  }
  protected onReset(): void {
    resetExercise(this.api, this.store, this.exerciseId()!);
  }
  protected onComplete(): void {
    completeExercise(this.api, this.store, this.exerciseId()!);
  }
  protected onStop(): void {
    stopExercise(this.api, this.exerciseId()!, () => this.onExerciseStopped());
  }
  private onExerciseStopped(): void {
    this.ws.disconnect();
    this.router.navigate(["/"]);
  }
  protected onSpeedChange(e: Event): void {
    const target = e.target;
    if (!(target instanceof HTMLInputElement)) return;
    this.api
      .setSpeed(this.exerciseId()!, parseFloat(target.value))
      .subscribe();
  }

  private eid(): number {
    return this.exerciseId()!;
  }
  protected triggerEvent(id: string): void {
    this.api.triggerEvent(this.eid(), id).subscribe();
  }
  protected cancelEvent(id: string): void {
    this.api.cancelEvent(this.eid(), id).subscribe();
  }
  protected completeEvent(id: string): void {
    this.api.completeEvent(this.eid(), id).subscribe();
  }
  protected activateIssue(id: string): void {
    this.api.activateIssue(this.eid(), id).subscribe();
  }
  protected mitigateIssue(id: string): void {
    this.api.mitigateIssue(this.eid(), id).subscribe();
  }
  protected resolveIssue(id: string): void {
    this.api.resolveIssue(this.eid(), id).subscribe();
  }
}

