import { inject, Injectable } from "@angular/core";
import { HttpClient } from "@angular/common/http";
import { Observable } from "rxjs";
import { environment } from "./environment";
import type { RoleDef } from "./scenario-api.service";

export type { RoleDef as RoleInfo } from "./scenario-api.service";

export interface DecisionOption {
  id: string;
  label: string;
  score?: number;
  role?: string | null;
}

export interface ActiveDecision {
  id: string;
  event_id: string | null;
  issue_id: string | null;
  title: string;
  description: string;
  question_type: string;
  options: DecisionOption[];
  completion_mode: string;
  target_roles: string[];
  timeout_ms: number;
  max_selections: number | null;
  status: string;
  opened_at_pt_ms: number;
  closed_at_pt_ms: number | null;
  recommendations: Record<string, string>;
}

export interface DecisionSubmission {
  participant_id: string;
  participant_name: string;
  selected_options: string[] | null;
  free_text: string | null;
}

export interface DecisionResponseItem {
  id: number;
  participant_name: string;
  selected_options: string[] | null;
  free_text: string | null;
  score: number | null;
  submitted_at: string;
}

export interface DecisionDetail {
  id: number;
  exercise_id: number;
  issue_id: string;
  title: string;
  description: string;
  question_type: string;
  options: DecisionOption[] | null;
  completion_mode: string;
  status: string;
  created_at: string;
  closed_at: string | null;
  responses: DecisionResponseItem[];
}

export interface ScenarioContext {
  title: string;
  description: string;
  briefing: string;
  objectives: string[];
  rules: string[];
  roles: RoleDef[];
}

@Injectable({ providedIn: "root" })
export class DecisionApiService {
  private readonly http = inject(HttpClient);
  private readonly base = environment.apiBaseUrl;

  /** Get open decisions from the engine */
  getEngineDecisions(exerciseId: number): Observable<ActiveDecision[]> {
    return this.http.get<ActiveDecision[]>(
      `${this.base}/api/exercises/${exerciseId}/engine/decisions`,
    );
  }

  /** Submit a response to a DB-persisted decision */
  submitResponse(
    decisionId: number,
    submission: DecisionSubmission,
  ): Observable<DecisionResponseItem> {
    return this.http.post<DecisionResponseItem>(
      `${this.base}/api/decisions/${decisionId}/responses`,
      submission,
    );
  }

  /** Get decision details with all responses (for GM observation) */
  getDecisionDetail(decisionId: number): Observable<DecisionDetail> {
    return this.http.get<DecisionDetail>(
      `${this.base}/api/decisions/${decisionId}`,
    );
  }

  /** List all decisions for an exercise */
  listDecisions(
    exerciseId: number,
    status?: string,
  ): Observable<DecisionDetail[]> {
    const params: Record<string, string | number> = { exercise_id: exerciseId };
    if (status) {
      params["status"] = status;
    }
    return this.http.get<DecisionDetail[]>(`${this.base}/api/decisions`, {
      params,
    });
  }

  /** Submit an advisor recommendation on an open decision */
  submitRecommendation(
    exerciseId: number,
    decisionId: string,
    optionId: string,
    participantId: string,
    roleId?: string,
  ): Observable<unknown> {
    const body: Record<string, string> = {
      decision_id: decisionId,
      option_id: optionId,
      participant_id: participantId,
    };
    if (roleId) {
      body["role_id"] = roleId;
    }
    return this.http.post(
      `${this.base}/api/exercises/${exerciseId}/engine/decisions/recommend`,
      body,
    );
  }

  /** Close a decision in the engine (GM or decision-maker action) */
  closeEngineDecision(
    exerciseId: number,
    decisionId: string,
    selectedOptionIds: string[] = [],
  ): Observable<unknown> {
    return this.http.post(
      `${this.base}/api/exercises/${exerciseId}/engine/decisions/${decisionId}/close`,
      { selected_option_ids: selectedOptionIds },
    );
  }

  /** Get scenario context/reference info */
  getContext(exerciseId: number): Observable<ScenarioContext> {
    return this.http.get<ScenarioContext>(
      `${this.base}/api/exercises/${exerciseId}/engine/context`,
    );
  }
}

import {
  ChangeDetectionStrategy,
  Component,
  computed,
  input,
  model,
} from "@angular/core";
import { DrawerPanelComponent } from "@aspect/ui";
import type { DecisionSnapshot, DecisionOptionSnapshot } from "../core/generated/state-changes.types";
import type { RoleDef } from "../core/scenario-api.service";

interface DecisionLogEntry {
  turnNumber: number;
  title: string;
  status: string;
  recommendations: { roleLabel: string; optionLabel: string }[];
  finalDecision: string[] | null;
}

@Component({
  selector: "tfc-logs-drawer",
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [DrawerPanelComponent],
  styleUrl: "./components-logs.css",
  template: `
    <ui-drawer-panel side="right" [open]="open()" (closed)="open.set(false)">
      <h2 drawerTitle>Decision Log</h2>
      <div class="decision-log">
        @for (entry of decisionLog(); track entry.turnNumber) {
          <div class="decision-entry" [attr.data-status]="entry.status" data-testid="decision-entry">
            <div class="decision-header">
              <span class="decision-turn">Turn {{ entry.turnNumber }}</span>
              <span class="decision-title">{{ entry.title }}</span>
            </div>
            @if (entry.recommendations.length > 0) {
              <div class="decision-recommendations">
                @for (rec of entry.recommendations; track rec.roleLabel) {
                  <div class="decision-rec" data-testid="recommendation">
                    <span class="decision-rec__role">{{ rec.roleLabel }}</span>
                    <span class="decision-rec__arrow">&rarr;</span>
                    <span class="decision-rec__option">{{ rec.optionLabel }}</span>
                  </div>
                }
              </div>
            }
            @if (entry.finalDecision) {
              <div class="decision-final" data-testid="final-decision">
                <span class="decision-final__label">Final</span>
                <span class="decision-final__arrow">&rarr;</span>
                <span class="decision-final__option">{{ entry.finalDecision.join(', ') }}</span>
              </div>
            } @else {
              <div class="decision-pending">Awaiting decision...</div>
            }
          </div>
        } @empty {
          <p class="logs-empty">No decisions yet.</p>
        }
      </div>
    </ui-drawer-panel>
  `,
})
export class LogsDrawerComponent {
  readonly open = model(false);
  readonly decisions = input<DecisionSnapshot[]>([]);
  readonly roles = input<RoleDef[]>([]);

  protected decisionLog = computed<DecisionLogEntry[]>(() => {
    const decisions = this.decisions();
    const roles = this.roles();
    const roleMap = new Map(roles.map((r) => [r.id, r.label]));

    return decisions
      .slice()
      .sort((a, b) => a.opened_at_pt_ms - b.opened_at_pt_ms)
      .map((d, i) => this.toLogEntry(d, i + 1, roleMap));
  });

  private toLogEntry(
    d: DecisionSnapshot,
    turnNumber: number,
    roleMap: Map<string, string>,
  ): DecisionLogEntry {
    const optionMap = new Map<string, string>(
      d.options.map((o: DecisionOptionSnapshot) => [o.id, o.label]),
    );

    const recommendations = Object.entries(d.recommendations).map(
      ([key, optionId]) => {
        const roleId = key.includes(":") ? key.split(":")[1] : key;
        return {
          roleLabel: roleMap.get(roleId) ?? roleId,
          optionLabel: optionMap.get(optionId) ?? optionId,
        };
      },
    );

    const finalDecision =
      d.status === "closed" && d.selected_option_ids.length > 0
        ? d.selected_option_ids.map((id) => optionMap.get(id) ?? id)
        : null;

    return {
      turnNumber,
      title: d.title,
      status: d.status,
      recommendations,
      finalDecision,
    };
  }
}

